function inspect(x:number,y:number){const r=renderer.domElement.getBoundingClientRect();let selected:THREE.Mesh|undefined;let best=Infinity;const projected=new THREE.Vector3();const radius=Math.max(48,Math.min(r.width,r.height)*.09);for(const mesh of clueMeshes){const id=mesh.userData['clueId'];if(typeof id!=='string'||state.discoveredClueIds.includes(id))continue;if(!isClueWithinRange(player.position.x,player.position.z,mesh.position.x,mesh.position.z,3.1))continue;mesh.getWorldPosition(projected);projected.project(camera);if(projected.z < -1||projected.z>1)continue;const sx=r.left+(projected.x+1)*.5*r.width,sy=r.top+(1-projected.y)*.5*r.height,d=Math.hypot(x-sx,y-sy);if(d<radius&&d<best){selected=mesh;best=d;}}if(!selected){notify('Walk closer to a glowing clue to inspect it.');return;}const id=selected.userData['clueId'];if(typeof id!=='string')return;const next=discoverClue(state,id,clues);if(next===state){notify('This clue is already recorded.');return;}state=next;selected.visible=false;const clue=clues.find(item=>item.id===id)!;if(id==='note'){fountainPuzzleState=createPuzzleState(fountainPuzzle,state.discoveredClueIds);document.querySelector<HTMLButtonElement>('#puzzle-open')!.hidden=false;}notify('Evidence collected: '+clue.title);document.querySelector('#count')!.textContent=String(state.discoveredClueIds.length);const list=document.querySelector('#evidence')!;list.replaceChildren(...state.discoveredClueIds.map(found=>{const item=document.createElement('button');item.type='button';item.className='clue';item.dataset['clueId']=found;item.textContent='✦ '+clues.find(item=>item.id===found)!.title;return item;}));if(state.discoveredClueIds.length===3){const completionHint=document.querySelector<HTMLElement>('#hint');if(completionHint){completionHint.textContent='';completionHint.style.display='none';}document.querySelector('#status')!.textContent='EVIDENCE COLLECTION COMPLETE';const deductionOpen=document.querySelector<HTMLButtonElement>('#deduction-open');if(deductionOpen)deductionOpen.hidden=false;}}
